"""Batch selected work rows without widening their transaction or ownership."""
from __future__ import annotations

import json
import sqlite3
from collections.abc import Mapping
from itertools import islice


def _check_materials(connection: sqlite3.Connection, materials: Mapping[str, str], *, native: bool) -> bool:
    """An ignored insert must still match the exact freshly generated bytes."""
    rows = iter((identity, value, len(value.encode("utf-8"))) for identity, value in materials.items())
    while batch := tuple(islice(rows, 256)):
        if native and sum(len(identity.encode()) + length + 24 for identity, _, length in batch) <= 64 * 1024 and not any(
            "\x00" in identity or "\x00" in value for identity, value, _ in batch
        ):
            try:
                mismatch = connection.execute(
                    "SELECT 1 FROM json_each(?) e LEFT JOIN run_materials m "
                    "ON m.material_id=json_extract(e.value,'$[0]') WHERE "
                    "m.material_id COLLATE BINARY IS NOT json_extract(e.value,'$[0]') "
                    "OR m.value COLLATE BINARY IS NOT json_extract(e.value,'$[1]') "
                    "OR m.byte_length IS NOT json_extract(e.value,'$[2]') "
                    "OR typeof(m.material_id)!='text' OR typeof(m.value)!='text' "
                    "OR typeof(m.byte_length)!='integer' LIMIT 1",
                    (json.dumps(batch, ensure_ascii=False, separators=(",", ":")),),
                ).fetchone()
                if mismatch is not None:
                    raise ValueError("Invalid SQLite Run material identity")
                continue
            except sqlite3.OperationalError as error:
                if "no such function" not in str(error) and "no such table: json_each" not in str(error):
                    raise
                native = False
        for identity, value, length in batch:
            actual = connection.execute(
                "SELECT value,byte_length FROM run_materials WHERE material_id=?", (identity,),
            ).fetchone()
            if (actual != (value, length) or not isinstance(actual[0], str) or type(actual[1]) is not int):
                raise ValueError("Invalid SQLite Run material identity")
    return native


def patch_work_objects(
    connection: sqlite3.Connection, run_id: str, *, replacements: Mapping[str, tuple[str, str]],
    deleted: set[str], materials: Mapping[str, str], references: Mapping[str, set[str]], native: bool,
) -> bool:
    """Replace exact selected paths; reclaim only their released dependencies."""
    # Shared batching remains defined by the mutation module; importing at the
    # call boundary avoids a module initialization cycle.
    from agent_run.sqlite_mutations import _batch

    removed: set[str] = set()
    paths = iter(replacements.keys() | deleted)
    while batch := tuple(islice(paths, 256)):
        predicate = "run_id=? AND object_path IN (" + ",".join("?" for _ in batch) + ")"
        parameters = (run_id, *batch)
        removed.update(row[0] for row in connection.execute(
            "SELECT DISTINCT material_id FROM run_object_material_refs WHERE " + predicate, parameters,
        ))
        connection.execute("DELETE FROM run_object_material_refs WHERE " + predicate, parameters)
    native = _batch(connection, ((identity, value, len(value.encode("utf-8"))) for identity, value in materials.items()),
        sql="INSERT OR IGNORE INTO run_materials VALUES (?, ?, ?)",
        native_sql="INSERT OR IGNORE INTO run_materials SELECT json_extract(value, '$[0]'), json_extract(value, '$[1]'), json_extract(value, '$[2]') FROM json_each(?)", native=native)
    native = _check_materials(connection, materials, native=native)
    native = _batch(connection, ((run_id, path) for path in deleted),
        sql="DELETE FROM run_objects WHERE run_id = ? AND object_path = ?",
        native_sql="DELETE FROM run_objects WHERE (run_id, object_path) IN (SELECT json_extract(value, '$[0]'), json_extract(value, '$[1]') FROM json_each(?))", native=native)
    update = "ON CONFLICT(run_id, object_path) DO UPDATE SET kind=excluded.kind, value_json=excluded.value_json"
    native = _batch(connection, ((run_id, path, *item) for path, item in replacements.items()),
        sql="INSERT INTO run_objects VALUES (?, ?, ?, ?) " + update,
        native_sql="INSERT INTO run_objects SELECT json_extract(value, '$[0]'), json_extract(value, '$[1]'), json_extract(value, '$[2]'), json_extract(value, '$[3]') FROM json_each(?) WHERE true " + update, native=native)
    native = _batch(connection, ((run_id, path, identity) for path, identities in references.items() for identity in identities),
        sql="INSERT INTO run_object_material_refs VALUES (?, ?, ?)",
        native_sql="INSERT INTO run_object_material_refs SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]') FROM json_each(?)", native=native)
    native = _batch(connection, ((run_id, identity) for identity in {identity for identities in references.values() for identity in identities}),
        sql="INSERT OR IGNORE INTO run_material_refs(run_id,material_id) VALUES (?, ?)",
        native_sql="INSERT OR IGNORE INTO run_material_refs(run_id,material_id) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]') FROM json_each(?)", native=native)
    native = _batch(connection, ((run_id, identity, run_id, identity) for identity in removed),
        sql="DELETE FROM run_material_refs WHERE run_id=? AND material_id=? AND NOT EXISTS "
            "(SELECT 1 FROM run_object_material_refs WHERE run_id=? AND material_id=?)",
        native_sql="DELETE FROM run_material_refs WHERE (run_id,material_id) IN "
                   "(SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]') FROM json_each(?)) "
                   "AND NOT EXISTS (SELECT 1 FROM run_object_material_refs r WHERE r.run_id=run_material_refs.run_id AND r.material_id=run_material_refs.material_id)", native=native)
    return _batch(connection, ((identity, identity) for identity in removed),
        sql="DELETE FROM run_materials WHERE material_id=? AND NOT EXISTS "
            "(SELECT 1 FROM run_object_material_refs WHERE material_id=?)",
        native_sql="DELETE FROM run_materials WHERE material_id IN (SELECT json_extract(value,'$[0]') FROM json_each(?)) "
                   "AND NOT EXISTS (SELECT 1 FROM run_object_material_refs r WHERE r.material_id=run_materials.material_id)", native=native)
